// DOM-free Audio-owned consumer. The Combat/World owner retains cue truth.
export const EVENTS={punchLight:'C01',punchHeavy:'C02',knuckles:'C03',whoosh:'C04',blaster:'C05',rocketLaunch:'C06',fuse:'C07',explosionSmall:'C08',explosionLarge:'C09',hitConfirm:'C10',fluffBurst:'C11',treeShake:'C12',botAngry:'C13',botCollapse:'C14',woodBreak:'C15',stoneBreak:'C16',crystalBreak:'C17',dominoChain:'C18'};
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export async function createCombat({audioContext:ctx,destination,manifest,assetBaseUrl=new URL('./',import.meta.url),buffers:provided,random=Math.random,onActivity=()=>{}}={}){
 if(!ctx||!destination)throw Error('Inject existing AudioContext and WORLD_SFX destination');
 if(!manifest){const r=await fetch(new URL('manifest.json',assetBaseUrl));if(!r.ok)throw Error('Private combat manifest unavailable');manifest=await r.json();}
 const buffers=new Map(provided||[]),live=new Set(),seen=new Set(),last=new Map(),lastAt=new Map(),log=[],loaded=[],input=ctx.createGain(),comp=ctx.createDynamicsCompressor(),ceiling=ctx.createWaveShaper(),focus=ctx.createGain(),meter=ctx.createAnalyser();
 comp.threshold.value=-12;comp.knee.value=4;comp.ratio.value=20;comp.attack.value=.003;comp.release.value=.12;const curve=new Float32Array(4097);for(let i=0;i<curve.length;i++)curve[i]=Math.tanh((i/4096*2-1)*1.4)*.45/Math.tanh(1.4);ceiling.curve=curve;ceiling.oversample='4x';input.gain.value=.65;input.connect(comp).connect(ceiling).connect(focus).connect(meter).connect(destination);meter.fftSize=1024;const pcm=new Float32Array(1024);
 let active=false,generation=0,duckDb=0,queue=[],demoUntil=null,activityUntil=0,room='outdoor',experimental=false;
 const now=()=>ctx.currentTime,record=e=>{log.push(e);if(log.length>1000)log.shift();};
 async function prepare(){let i=0;const worker=async()=>{while(i<manifest.assets.length){const a=manifest.assets[i++];if(buffers.has(a.id))continue;const r=await fetch(new URL(a.file,assetBaseUrl));if(!r.ok)throw Error('Private asset unavailable '+a.id);const bytes=await r.arrayBuffer(),h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(h!==a.sha256)throw Error('Private SHA mismatch '+a.id);const b=await ctx.decodeAudioData(bytes);buffers.set(a.id,b);loaded.push({id:a.id,duration:b.duration,sampleRate:b.sampleRate});}};await Promise.all(Array.from({length:4},worker));}
 async function start(){const g=++generation;await prepare();if(g===generation)active=true;return snapshot();}
 function stop(){generation++;active=false;queue=[];demoUntil=null;activityUntil=0;for(const v of [...live]){try{v.s.stop();}catch{}cleanup(v);}onActivity(false);return snapshot();}
 function cleanup(v){live.delete(v);for(const n of v.nodes)n.disconnect();}
 function pick(family,key){const pool=manifest.assets.filter(a=>a.family===family),previous=last.get(key),choices=pool.filter(a=>a.id!==previous),a=choices[Math.floor(random()*choices.length)]||pool[0];if(a)last.set(key,a.id);return a;}
 function play(family,{at=now()+.01,gain=1,position={x:0,y:0,z:-1},layer='full',key=family}={}){
  if(live.size>=24){record({type:'voice-drop',at:now()});return null;}const a=pick(family,key);if(!a||!buffers.has(a.id))return null;const window=layer==='full'?{offset:0,duration:buffers.get(a.id).duration}:a.windows[layer],s=ctx.createBufferSource(),env=ctx.createGain(),filter=ctx.createBiquadFilter(),pan=ctx.createPanner(),rate=.96+random()*.08,volume=gain*10**((random()*4-2)/20),distance=Math.hypot(position.x,position.y,position.z),duration=window.duration/rate;
  s.buffer=buffers.get(a.id);s.playbackRate.value=rate;env.gain.setValueAtTime(0,at);env.gain.linearRampToValueAtTime(volume,at+.001);env.gain.setValueAtTime(volume,Math.max(at+.001,at+duration-.025));env.gain.linearRampToValueAtTime(0,at+duration);filter.type='lowpass';filter.frequency.value=Math.max(800,12000/(1+distance/18));pan.panningModel='HRTF';pan.distanceModel='inverse';pan.refDistance=3;pan.maxDistance=150;pan.rolloffFactor=1;for(const k of ['x','y','z'])pan['position'+k.toUpperCase()].value=position[k];s.connect(env).connect(filter).connect(pan).connect(input);const nodes=[s,env,filter,pan];
  if(room!=='outdoor'){const delay=ctx.createDelay(.1),wet=ctx.createGain();delay.delayTime.value=room==='small-room'?.027:.045;wet.gain.value=room==='small-room'?.10:.06;pan.connect(delay).connect(wet).connect(input);nodes.push(delay,wet);}
  const v={s,nodes,end:at+duration+.1};live.add(v);s.onended=()=>cleanup(v);s.start(at,window.offset,window.duration);s.stop(at+duration+.02);activityUntil=Math.max(activityUntil,at+duration+.2);record({type:'layer',family,id:a.id,layer,at,rate,gain:volume,position,lowpassHz:filter.frequency.value});return a.id;
 }
 function emit(e){
  if(!e||!EVENTS[e.type])throw Error('Unsupported combat event (no placeholder fallback)');
  if(e.position&&!['x','y','z'].every(k=>Number.isFinite(e.position[k])))throw Error('Invalid combat position');
  if(e.id!==undefined){if(typeof e.id!=='string'||!e.id)throw Error('Event id must be nonempty');if(seen.has(e.id))return null;seen.add(e.id);if(seen.size>512)seen.delete(seen.values().next().value);}
  if(!active)return null;const t=now(),family=EVENTS[e.type];if(t-(lastAt.get(e.type)??-Infinity)<.07)return null;lastAt.set(e.type,t);
  const position=e.type==='hitConfirm'?{x:0,y:0,z:-1}:e.position||{x:0,y:0,z:-1},at=t+.01,gain=Number.isFinite(e.intensity)?clamp(e.intensity,.1,1):.8,ids=[];
  if(experimental){for(const [i,layer] of ['attack','body','tail'].entries())ids.push(play(family,{at:at+[0,.025,.08][i],gain:gain*[.8,.55,.3][i],position,layer,key:family+layer}));}
  else{ids.push(play(family,{at,gain,position}));if(['punchLight','punchHeavy','knuckles'].includes(e.type))ids.push(play('C04',{at,gain:.18,position,key:'motion'}));if(['explosionSmall','explosionLarge'].includes(e.type)&&['wood','stone','crystal'].includes(e.material)){const material={wood:'C15',stone:'C16',crystal:'C17'}[e.material];ids.push(play(material,{at:at+.1,gain:.25,position,key:'debris-'+material}));}}
  record({type:'event',event:e.type,id:e.id||null,at,ids,composition:experimental?'EXPERIMENTAL_DERIVED_LAYERS':'PHYSICAL_DONOR_COMPOSITION'});return ids;
 }
function schedule(kind,event='punchLight',options={}){if(!['ten','fight'].includes(kind)||!EVENTS[event])throw Error('Invalid audition');const t=now();queue=[];if(kind==='ten'){for(let i=0;i<10;i++)queue.push({...options,at:t+i*.8,type:event});demoUntil=t+10;}else{const sequence=['whoosh','punchLight','punchHeavy','blaster','rocketLaunch','explosionSmall','woodBreak','botAngry','knuckles','hitConfirm','treeShake','stoneBreak','fluffBurst','explosionLarge','botCollapse','crystalBreak','dominoChain'];for(let i=0;i<30;i++)queue.push({at:t+i,type:sequence[i%sequence.length],...options,material:options.material||(i%2?'wood':'stone')});demoUntil=t+30;}return snapshot();}
 function tick(){if(!active)return;const t=now();while(queue.length&&queue[0].at<=t){const e=queue.shift();if(t-e.at<.15)emit(e);else record({type:'late-cue-dropped',event:e.type,at:t});}for(const v of [...live])if(t>v.end)cleanup(v);onActivity(t<activityUntil);if(demoUntil!==null&&t>=demoUntil&&live.size===0){queue=[];demoUntil=null;record({type:'demo-complete',at:t});}}
 function setMix(mix){const db=mix.musicActive||mix.dialogueActive?-3:0;if(db!==duckDb){duckDb=db;focus.gain.setTargetAtTime(10**(db/20),now(),db<0?.08:.5);}}
 function setContext(update){if(update.room!==undefined){if(!['outdoor','small-room','forest'].includes(update.room))throw Error('Invalid room');room=update.room;}if(update.experimentalLayers!==undefined)experimental=!!update.experimentalLayers;}
 function snapshot(){meter.getFloatTimeDomainData(pcm);return {schema:'kfb.combat-sfx/1',active,loaded:buffers.size,decode:loaded.slice(),activeSources:live.size,queued:queue.length,demoUntil,combatActive:active&&now()<activityUntil,duckDb,room,experimentalLayers:experimental,rms:Math.sqrt(pcm.reduce((s,x)=>s+x*x,0)/pcm.length),limiterReductionDb:comp.reduction,moduleCreatedAudioContexts:0,clock:'injected AudioContext.currentTime / host tick',earAcceptance:'OPEN',log:log.slice()};}
 return {prepare,start,stop,emit,tick,schedule,setMix,setContext,snapshot,createCapture:()=>{const tap=ctx.createMediaStreamDestination();meter.connect(tap);return {stream:tap.stream,disconnect:()=>meter.disconnect(tap)};}};
}
